LIB.push(
{t:"Reazione a catena ed effetto domino",c:"sis",tg:"Un singolo evento può innescare una serie di conseguenze che si propagano.",d:2,
sp:"In una fila di tessere del domino, basta spingerne una per farle cadere tutte. In una reazione a catena, ogni evento ne provoca un altro. Molti fenomeni funzionano così: un ritardo che causa altri ritardi, un debito che porta ad altri debiti, un gesto gentile che si diffonde. Il modello ti aiuta a individuare la prima tessera e a creare interruzioni prima che la catena diventi incontrollabile.",
ap:["Le catene si formano quando le parti sono collegate strettamente e senza margini: un treno in ritardo fa perdere la coincidenza, che fa saltare la riunione, che rimanda la decisione. Più i collegamenti sono stretti, più la catena è veloce e lunga.","Per usarlo, cerca i punti in cui una piccola caduta può propagarsi e crea interruzioni: margini di tempo, scorte, alternative. Ma puoi usare la catena anche a tuo favore: individua la prima tessera di un cambiamento positivo, come un'abitudine che ne trascina altre."],
ri:[["Una cosa porta all'altra","Un piccolo problema ne genera molti."],["Collegamenti stretti","Ogni parte dipende dalla precedente senza margine."],["Effetti a valanga","La situazione peggiora sempre più in fretta."]],
es:[["Te stesso","Andare a letto tardi porta a svegliarti tardi, saltare la colazione, mangiare male a pranzo. Sistemi la prima tessera: l'orario della sera."],["Lavoro","Un fornitore in ritardo blocca tutta la produzione. L'azienda tiene una piccola scorta per interrompere la catena."]],
ex:["Ripensa a una giornata storta e ricostruisci la catena fino alla prima tessera.","Individua un punto della tua settimana dove un ritardo si propaga e aggiungi un margine.","Scegli un'abitudine positiva che potrebbe innescarne altre e iniziala."],
q:["Qual è la prima tessera di questa catena?","Dove posso inserire un'interruzione?","Quale piccola azione positiva potrebbe trascinarne altre?"],
er:"Intervenire sull'ultima tessera caduta invece che sulla prima.",
qz:[["Quando una reazione a catena si propaga più facilmente?",["Quando ci sono molti margini","Quando le parti sono collegate strettamente senza margini","Quando nulla è collegato","Mai"],1,"I collegamenti stretti accelerano la propagazione."],["Come fermare un effetto domino?",["Accelerare","Inserire interruzioni come margini e alternative","Ignorarlo","Aggiungere collegamenti"],1,"Le interruzioni bloccano la propagazione."]]},

{t:"La vendita Challenger",c:"com",tg:"I venditori migliori insegnano qualcosa di nuovo al cliente e lo guidano con decisione.",d:2,
sp:"Matthew Dixon e Brent Adamson hanno studiato migliaia di venditori e scoperto che i più efficaci non sono quelli che costruiscono solo buone relazioni, ma quelli che sfidano il cliente: gli insegnano qualcosa di nuovo sul suo problema, adattano il messaggio alla persona e guidano la conversazione verso una decisione. Il modello vale per vendere, ma anche per convincere chiunque.",
ap:["Le tre azioni chiave sono insegnare (portare un punto di vista che il cliente non aveva), adattare (parlare dei problemi specifici di quella persona) e prendere il controllo (non avere paura di parlare di costi e decisioni). Il cliente apprezza chi lo aiuta a vedere meglio la propria situazione.","Sfidare non significa essere aggressivi. Significa offrire valore con un'idea utile, anche scomoda, invece di dire solo ciò che l'altro vuole sentire. Funziona se conosci davvero il problema dell'altro."],
ri:[["Relazione senza risultati","Il cliente ti trova simpatico ma non decide."],["Il cliente sa già tutto","Non porti nessuna idea nuova."],["Paura di parlare di soldi","Eviti i temi difficili."]],
es:[["Lavoro","Un consulente informatico mostra a un'azienda quanto tempo perde con un processo manuale che non aveva mai calcolato. L'azienda decide di investire."],["Te stesso","Proponi a un amico di fare sport insieme. Invece di insistere, gli mostri un dato sul suo mal di schiena e un piano adatto ai suoi orari."]],
ex:["Prima di proporre qualcosa, scrivi un'idea nuova e utile che l'altro probabilmente non conosce.","Adatta la tua proposta a due persone diverse con problemi diversi.","Nella prossima conversazione importante, porta tu il discorso verso una decisione concreta."],
q:["Cosa posso insegnare all'altro sul suo problema?","Come adatto il messaggio a questa persona?","Sto evitando di parlare della decisione o dei costi?"],
er:"Confondere la sfida con la prepotenza.",
qz:[["Cosa fa un venditore Challenger?",["Asseconda sempre il cliente","Insegna qualcosa di nuovo, adatta il messaggio e guida verso la decisione","Abbassa i prezzi","Parla solo di sé"],1,"Sono le tre azioni chiave."],["Cosa NON significa sfidare il cliente?",["Portare un'idea nuova","Essere aggressivi","Parlare di costi","Guidare la decisione"],1,"Sfidare significa offrire valore, non imporsi."]]},

{t:"I sei principi di influenza di Cialdini",c:"com",tg:"Reciprocità, impegno, prova sociale, autorità, simpatia e scarsità guidano i nostri sì.",d:2,
sp:"Lo psicologo Robert Cialdini ha individuato sei principi che spingono le persone a dire sì: reciprocità (ricambiamo ciò che riceviamo), impegno e coerenza (restiamo fedeli a ciò che abbiamo detto), prova sociale (facciamo ciò che fanno gli altri), autorità (seguiamo gli esperti), simpatia (diciamo sì a chi ci piace) e scarsità (vogliamo ciò che è raro). Conoscerli ti aiuta a convincere onestamente e a difenderti dalle manipolazioni.",
ap:["Questi principi sono scorciatoie utili: di solito ha senso ricambiare, seguire un esperto o fare come gli altri. Ma chi vuole venderti qualcosa li usa apposta: un campione gratuito (reciprocità), «ultimi pezzi» (scarsità), «scelto da un milione di clienti» (prova sociale). Più tardi Cialdini ha aggiunto un settimo principio, l'unità: il senso di appartenenza a un gruppo.","Per difenderti, quando senti una spinta forte a dire sì chiediti quale principio sta agendo e se, senza di esso, la proposta ti convincerebbe ancora. Per convincere in modo etico, usa solo principi veri: autorità reale, scarsità reale, prove sociali reali."],
ri:[["Pressione a decidere subito","«Solo per oggi»."],["Ti senti in obbligo","Dopo un regalo o un favore."],["«Lo fanno tutti»","La popolarità sostituisce le ragioni."]],
es:[["Acquisti","Un sito mostra «12 persone stanno guardando questa camera». Riconosci prova sociale e scarsità e decidi con calma."],["Lavoro","Per convincere i colleghi a usare un nuovo metodo, mostri che due reparti lo usano già con successo (prova sociale reale)."]],
ex:["Per una settimana, annota ogni volta che riconosci uno dei sei principi in pubblicità o conversazioni.","Prima di un acquisto impulsivo, chiediti quale principio ti sta spingendo.","Prepara una tua richiesta usando onestamente due principi."],
q:["Quale principio mi sta spingendo a dire sì?","Senza questa spinta, la proposta mi convincerebbe?","Sto usando questi principi in modo onesto?"],
er:"Usarli per manipolare: quando le persone se ne accorgono, la fiducia crolla.",
qz:[["Un negozio dice «Solo 3 pezzi rimasti». Quale principio usa?",["Reciprocità","Autorità","Scarsità","Simpatia"],2,"Ciò che è raro sembra più desiderabile."],["Come difendersi da questi principi?",["Dire sempre no","Chiedersi se la proposta convince anche senza la spinta","Comprare subito","Ignorare le offerte"],1,"Separa la spinta dal valore reale."]]},

{t:"Cerchio di preoccupazione e influenza",c:"app",tg:"Concentra l'energia su ciò che puoi influenzare, non su tutto ciò che ti preoccupa.",d:1,
sp:"Stephen Covey propone di immaginare due cerchi. Il cerchio di preoccupazione contiene tutto ciò che ti preoccupa: economia, politica, salute, opinioni degli altri. Dentro c'è un cerchio più piccolo, quello di influenza: le cose su cui puoi davvero agire. Le persone efficaci concentrano le energie nel secondo cerchio, che così si allarga.",
ap:["Passare il tempo a lamentarsi di ciò che non controlli crea ansia e senso di impotenza, e riduce la tua influenza. Concentrarti su ciò che puoi fare, anche piccolo, ti dà potere e spesso allarga ciò che puoi cambiare.","Per usarlo, scrivi le tue preoccupazioni e dividile: cosa posso controllare direttamente, cosa posso influenzare in parte, cosa non posso cambiare. Per l'ultima categoria, puoi solo scegliere come reagire."],
ri:[["Lamentele continue","Parli molto di ciò che non va e fai poco."],["Ansia per le notizie","Ti preoccupi di eventi lontani."],["Senso di impotenza","Ti sembra che nulla dipenda da te."]],
es:[["Lavoro","Ti preoccupa una possibile crisi del settore. Non puoi fermarla, ma puoi aggiornare le competenze e risparmiare un fondo di emergenza."],["Salute","Ti preoccupi per la salute di un genitore. Non controlli la malattia, ma puoi accompagnarlo alle visite e organizzare l'aiuto in casa."]],
ex:["Scrivi dieci preoccupazioni e dividile in tre gruppi: controllo, influenzo, non posso cambiare.","Per ogni cosa che controlli, scrivi una piccola azione e falla questa settimana.","Riduci di metà il tempo dedicato a notizie su cose che non puoi cambiare."],
q:["Questa cosa è nel mio cerchio di influenza?","Cosa posso fare, anche di piccolo?","Su cosa posso solo scegliere come reagire?"],
er:"Usare il modello per ignorare problemi importanti che si possono influenzare insieme ad altri.",
qz:[["Cosa contiene il cerchio di influenza?",["Tutto ciò che ti preoccupa","Le cose su cui puoi davvero agire","Solo il lavoro","Le opinioni degli altri"],1,"È lo spazio della tua azione concreta."],["Cosa succede concentrandosi sul cerchio di influenza?",["Si restringe","Tende ad allargarsi","Non cambia nulla","Aumenta l'ansia"],1,"Agire aumenta ciò che puoi cambiare."]]},

{t:"COM-B e cambiamento del comportamento",c:"app",tg:"Un comportamento avviene solo se ci sono capacità, opportunità e motivazione.",d:2,
sp:"Il modello COM-B, sviluppato da Susan Michie, dice che per fare qualcosa servono tre ingredienti: Capacità (so e posso farlo, fisicamente e mentalmente), Opportunità (l'ambiente e le persone lo permettono) e Motivazione (lo voglio, per abitudine o per scelta). Se un comportamento non avviene, manca almeno uno dei tre.",
ap:["Spesso pensiamo che le persone non facciano qualcosa per mancanza di volontà. Ma magari non sanno come (capacità), non hanno tempo, spazio o strumenti (opportunità), o la motivazione è più debole di altre spinte. Ogni mancanza richiede una soluzione diversa.","Per usarlo, davanti a un comportamento che vuoi cambiare chiediti quale dei tre manca. Formazione per la capacità, cambiamenti dell'ambiente per l'opportunità, ricompense e significato per la motivazione."],
ri:[["«Non ha forza di volontà»","Attribuisci tutto alla motivazione."],["Buone intenzioni bloccate","Vuoi fare una cosa ma l'ambiente non aiuta."],["Comportamenti che non partono","Nonostante spiegazioni e incoraggiamenti."]],
es:[["Salute","Vuoi mangiare più verdura. Sai cucinarla (capacità), sei motivato, ma al supermercato vicino non c'è (opportunità). Ti iscrivi a un servizio di cassette di verdura."],["Famiglia","Il figlio non fa i compiti. Non è pigrizia: non capisce la matematica. Lo aiuti con un ripasso e i compiti ripartono."]],
ex:["Scegli un comportamento che vuoi adottare e valuta da 1 a 5 capacità, opportunità e motivazione.","Intervieni sull'ingrediente più debole con un'azione concreta.","Pensa a una persona che giudichi poco motivata: potrebbe mancarle capacità o opportunità?"],
q:["So e posso farlo?","L'ambiente me lo permette?","Lo voglio abbastanza, rispetto alle altre spinte?"],
er:"Cercare di aumentare la motivazione quando il problema è la capacità o l'opportunità.",
qz:[["Cosa significa la O di COM-B?",["Obiettivo","Opportunità","Organizzazione","Ottimismo"],1,"L'ambiente deve permettere il comportamento."],["Una persona motivata non riesce a fare sport perché lavora fino a tardi. Cosa manca?",["Capacità","Opportunità","Motivazione","Nulla"],1,"Manca il tempo, cioè l'opportunità."]]},

{t:"Euristica della conferma",c:"rag",tg:"Cerchiamo e ricordiamo le informazioni che confermano ciò che già pensiamo.",d:2,
sp:"Il bias di conferma è la tendenza a cercare, interpretare e ricordare le informazioni che confermano le nostre convinzioni, ignorando quelle contrarie. Se pensi che un collega sia pigro, noterai ogni suo ritardo e dimenticherai i giorni in cui ha lavorato bene. Il modello ti invita a cercare attivamente le prove che potrebbero smentirti.",
ap:["Questo errore è potente perché ci fa sentire sempre più sicuri di avere ragione, anche quando abbiamo torto. Gli algoritmi dei social lo amplificano mostrandoci contenuti simili a ciò che già ci piace. Più un tema ci tocca emotivamente, più il bias è forte.","Per contrastarlo chiediti: cosa mi farebbe cambiare idea? Cerca la versione più forte dell'opinione opposta. Chiedi a qualcuno che la pensa diversamente. E nelle decisioni importanti, scrivi prima quali dati ti farebbero scegliere in modo diverso."],
ri:[["Sei sempre più sicuro","Ogni informazione sembra confermare la tua idea."],["Fonti tutte uguali","Leggi solo chi la pensa come te."],["Le prove contrarie ti irritano","Le scarti senza esaminarle."]],
es:[["Soldi","Hai comprato un'azione e leggi solo articoli positivi. Ti sforzi di cercare tre analisi critiche prima di investire ancora."],["Relazioni","Pensi che un'amica sia distante. Annoti per una settimana anche i suoi gesti gentili e scopri che ce ne sono molti."]],
ex:["Scegli una tua convinzione forte e cerca il miglior argomento contrario.","Per una settimana segui una fonte di informazione con punti di vista diversi dai tuoi.","Prima di una decisione, scrivi quali informazioni ti farebbero cambiare scelta."],
q:["Sto cercando prove o solo conferme?","Qual è l'argomento migliore contro la mia idea?","Cosa mi farebbe cambiare idea?"],
er:"Pensare di esserne immuni perché si è intelligenti: anzi, sappiamo trovare argomenti migliori per difendere ciò che pensiamo.",
qz:[["Cos'è il bias di conferma?",["Confermare un appuntamento","Cercare e ricordare soprattutto ciò che conferma le proprie idee","Cambiare idea spesso","Fidarsi degli esperti"],1,"Filtriamo le informazioni a favore delle nostre convinzioni."],["Qual è un buon antidoto?",["Leggere solo fonti amiche","Cercare attivamente il miglior argomento contrario","Evitare le discussioni","Decidere in fretta"],1,"Mettere alla prova le proprie idee le rende più solide."]]},

{t:"Analisi costi-benefici",c:"eco",tg:"Metti per iscritto cosa guadagni e cosa perdi prima di decidere.",d:1,
sp:"L'analisi costi-benefici consiste nell'elencare tutti i costi e tutti i benefici di una scelta, dare a ciascuno un peso e confrontarli. Sembra ovvio, ma spesso decidiamo guardando solo un lato: il beneficio che desideriamo o il costo che temiamo. Mettere tutto per iscritto rende la decisione più chiara e onesta.",
ap:["I costi non sono solo soldi: contano tempo, fatica, stress, rischi e opportunità perse. Anche i benefici possono essere economici, emotivi o di lungo periodo. Alcuni sono facili da misurare, altri no: conviene comunque nominarli.","Il modello ha limiti: è difficile pesare cose diverse, come soldi e felicità, e c'è il rischio di manipolare i numeri per arrivare alla conclusione desiderata. Usalo come strumento per pensare, non come calcolo che decide al posto tuo."],
ri:[["Decisioni d'impulso","Scegli guardando solo il lato positivo."],["Paralisi","Ti fermi davanti a un solo costo."],["Costi nascosti","Tempo, manutenzione, stress non considerati."]],
es:[["Casa","Pensi di comprare un cane. Elenchi benefici (compagnia, movimento) e costi (spese, tempo, vacanze più complicate). Decidi con più serenità."],["Lavoro","Valuti un corso serale costoso. Metti nei benefici il possibile aumento e nei costi anche le sere perse con la famiglia."]],
ex:["Per una decisione aperta, scrivi due colonne con almeno cinque costi e cinque benefici.","Dai un peso da 1 a 5 a ogni voce e confronta i totali.","Aggiungi alla lista i costi non economici che di solito trascuri."],
q:["Quali sono tutti i costi, anche non economici?","Quali sono tutti i benefici, anche futuri?","Sto truccando i pesi per arrivare dove voglio?"],
er:"Credere che i numeri dell'analisi siano oggettivi anche quando sono stime personali.",
qz:[["Cosa include un'analisi costi-benefici completa?",["Solo i soldi","Anche tempo, fatica, rischi e opportunità perse","Solo i benefici","Solo i costi immediati"],1,"I costi non sono solo economici."],["Qual è un limite del modello?",["È troppo semplice","È difficile pesare cose diverse e si può manipolare il calcolo","Non serve mai","È vietato"],1,"Va usato come aiuto, non come verità."]]},

{t:"Il test CRAAP per le fonti",c:"rag",tg:"Valuta una fonte per attualità, rilevanza, autorità, accuratezza e scopo.",d:1,
sp:"Il test CRAAP, nato in una biblioteca universitaria in California, è una lista di cinque domande per capire se una fonte è affidabile: è Attuale (quando è stata scritta)? È Rilevante per la tua domanda? Chi è l'Autore e che competenze ha? È Accurata, cioè supportata da prove e verificabile? Qual è lo Scopo: informare, vendere, convincere?",
ap:["Online tutto sembra ugualmente credibile: un blog anonimo e uno studio scientifico possono apparire uno accanto all'altro. Il test ti obbliga a fermarti e controllare. Spesso basta guardare la data, l'autore e chi pubblica per capire molto.","Non serve fare tutto il test per ogni notizia. Usalo quando l'informazione è importante per una decisione (salute, soldi, voto) o quando stai per condividerla con altri."],
ri:[["Notizie senza data o autore","Non sai chi l'ha scritto né quando."],["Siti che vendono qualcosa","L'informazione serve a convincerti a comprare."],["Affermazioni senza prove","Nessun dato, studio o fonte citata."]],
es:[["Salute","Leggi di una dieta miracolosa. Il sito vende integratori, l'articolo non ha autore né studi. Il test ti fa scartarla."],["Famiglia","Prima di condividere una notizia nel gruppo, controlli la data: è di cinque anni fa e non è più valida."]],
ex:["Applica il test completo alla prossima notizia importante che leggi.","Prima di condividere qualcosa questa settimana, controlla almeno data e autore.","Confronta due fonti sullo stesso tema usando le cinque domande."],
q:["Quando è stata scritta, e chi l'ha scritta?","Su quali prove si basa?","Qual è lo scopo di chi la pubblica?"],
er:"Scartare automaticamente una fonte per un solo criterio senza valutarla nel complesso.",
qz:[["Cosa verifica la A di «Autorità»?",["La data","Chi ha scritto la fonte e le sue competenze","Lo scopo commerciale","La lunghezza"],1,"Conta chi parla e cosa sa."],["Un articolo sulla salute è pubblicato da un sito che vende integratori. Quale criterio ti mette in allerta?",["Attualità","Scopo","Rilevanza","Lunghezza"],1,"Lo scopo potrebbe essere vendere, non informare."]]},

{t:"La zona della curiosità",c:"app",tg:"La curiosità è massima quando sai un po', ma non abbastanza.",d:2,
sp:"Non siamo curiosi di ciò che non conosciamo affatto né di ciò che sappiamo già bene. La curiosità nasce nella zona intermedia: quando sappiamo abbastanza da capire che c'è qualcosa che ci manca. Lo psicologo George Loewenstein la descrive come un vuoto di informazione che vogliamo colmare. Il modello ti aiuta a stimolare la curiosità tua e degli altri.",
ap:["Un film che svela tutto subito non incuriosisce; uno che non dà alcun indizio confonde. Le buone storie, le buone lezioni e le buone presentazioni aprono una domanda e lasciano intravedere la risposta. Anche per imparare, conviene partire da qualcosa che conosci e poi esplorare il confine.","Per accendere la curiosità: dai un po' di contesto, poi fai una domanda che non ha risposta ovvia. Per tenerla viva in te stesso, impara le basi di un argomento: la curiosità cresce con la conoscenza."],
ri:[["Noia","Un argomento ti sembra troppo noto o troppo lontano."],["Domande aperte","Senti il bisogno di sapere come va a finire."],["Lezioni che non coinvolgono","Troppe informazioni tutte insieme."]],
es:[["Famiglia","Per far appassionare un figlio alla storia, gli racconti l'inizio di un mistero storico e ti fermi alla domanda chiave. Il giorno dopo vuole sapere il resto."],["Lavoro","In una presentazione apri con una domanda: «Perché il 40% dei clienti abbandona al terzo mese?». Tutti ascoltano per scoprire la risposta."]],
ex:["Scegli un argomento che ti annoia e impara le basi per 15 minuti: diventa più interessante?","Nella prossima spiegazione che dai, apri con una domanda e lascia la risposta per dopo.","Scrivi tre domande su un tema che conosci un po' e cercane le risposte."],
q:["So abbastanza per essere curioso di questo?","Quale domanda posso lasciare aperta?","Sto dando troppe o troppo poche informazioni?"],
er:"Credere che la curiosità sia un tratto fisso: si coltiva imparando.",
qz:[["Quando è massima la curiosità?",["Quando non sai nulla","Quando sai un po' ma non abbastanza","Quando sai tutto","Mai"],1,"Il vuoto di informazione percepito ci spinge a cercare."],["Come rendere più coinvolgente una spiegazione?",["Dire tutto subito","Aprire con una domanda e lasciare intravedere la risposta","Usare parole difficili","Essere più lunghi"],1,"Crea un vuoto da colmare."]]},

{t:"Il quadro Cynefin",c:"sis",tg:"Capisci se la situazione è chiara, complicata, complessa o caotica, e agisci di conseguenza.",d:3,
sp:"Dave Snowden ha creato il quadro Cynefin (parola gallese che significa «luogo familiare») per scegliere come agire secondo il tipo di situazione. Nelle situazioni chiare basta seguire le regole. In quelle complicate serve un esperto che analizzi. In quelle complesse nessuno conosce la risposta: bisogna fare esperimenti. In quelle caotiche bisogna prima agire per stabilizzare. Quando non sai in che situazione sei, sei nella confusione.",
ap:["L'errore più comune è trattare una situazione complessa come se fosse complicata: chiamare esperti e fare piani dettagliati quando le cose cambiano reagendo alle tue azioni. Oppure trattare un'emergenza caotica con riunioni e analisi, quando serve prima mettere in sicurezza.","Per usarlo: chiaro, osserva e applica la regola; complicato, analizza e chiedi a chi sa; complesso, prova in piccolo, osserva e adatta; caotico, agisci subito, poi capisci. Le situazioni possono passare da un tipo all'altro."],
ri:[["Piani che falliscono","Usi un metodo adatto a un altro tipo di situazione."],["Esperti in disaccordo","Il problema è complesso, non complicato."],["Emergenza","Non c'è tempo per analizzare."]],
es:[["Famiglia","Montare un mobile è complicato: segui le istruzioni. Educare un adolescente è complesso: provi, osservi e adatti."],["Lavoro","Il server cade e i clienti non comprano: situazione caotica. Prima si ripristina il servizio, poi si analizza la causa."]],
ex:["Scegli tre problemi attuali e classificali come chiaro, complicato, complesso o caotico.","Per un problema complesso, progetta un piccolo esperimento invece di un piano completo.","Ripensa a un fallimento: hai usato il metodo adatto al tipo di situazione?"],
q:["Che tipo di situazione è questa?","Esiste una risposta nota o devo sperimentare?","Devo prima agire per stabilizzare?"],
er:"Usare sempre lo stesso approccio per tutti i problemi.",
qz:[["Come si agisce in una situazione complessa?",["Seguendo regole fisse","Facendo piccoli esperimenti, osservando e adattando","Chiedendo a un solo esperto","Senza agire"],1,"Nessuno conosce la risposta in anticipo."],["In una situazione caotica cosa si fa prima?",["Si analizza a lungo","Si agisce per stabilizzare","Si scrive un piano","Si aspetta"],1,"Prima mettere in sicurezza, poi capire."]]},

{t:"L'albero delle decisioni",c:"qua",tg:"Disegna le scelte, gli esiti possibili e le loro probabilità come rami di un albero.",d:2,
sp:"Un albero delle decisioni è un disegno che parte da una scelta e si apre in rami: le opzioni disponibili, poi gli esiti possibili di ciascuna, con le loro probabilità e conseguenze. Mettere la decisione su carta rende visibili alternative e rischi che a mente si confondono, e aiuta a confrontare le strade in modo più lucido.",
ap:["Si usano quadrati per le scelte che dipendono da te e cerchi per gli eventi incerti. Per ogni ramo stimi quanto è probabile e quanto vale l'esito. Moltiplicando probabilità e valore ottieni un'idea del valore atteso di ogni opzione.","Non serve essere precisi: anche stime approssimative rendono la decisione più chiara. Il vero vantaggio è vedere tutte le strade e chiedersi «cosa faccio se succede questo?». Il limite è che i numeri sono stime e alcune cose sono difficili da misurare."],
ri:[["Decisione con molte variabili","Non riesci a tenere tutto a mente."],["Eventi incerti","L'esito dipende da cose che non controlli."],["Scelte in sequenza","Una decisione ne apre altre."]],
es:[["Lavoro","Devi decidere se lanciare un prodotto ora o tra sei mesi. Disegni i rami: mercato favorevole o no, concorrente che arriva o no. Scopri che aspettare è più rischioso."],["Casa","Per un trasloco disegni le opzioni: affittare in centro o comprare in periferia, con gli scenari di lavoro da casa o in ufficio."]],
ex:["Disegna su un foglio l'albero di una decisione che stai rimandando.","Per ogni esito incerto, scrivi una probabilità approssimativa.","Aggiungi a ogni ramo cosa faresti se si verificasse lo scenario negativo."],
q:["Quali sono tutte le opzioni?","Cosa può succedere dopo ciascuna, e con che probabilità?","Cosa farei se si verificasse lo scenario peggiore?"],
er:"Considerare i numeri stimati come certezze.",
qz:[["Cosa rappresentano i cerchi in un albero delle decisioni?",["Le scelte","Gli eventi incerti","I costi","I risultati finali"],1,"I quadrati sono scelte, i cerchi eventi incerti."],["Qual è il vantaggio principale dell'albero?",["Dà risultati certi","Rende visibili opzioni, rischi ed esiti","Elimina l'incertezza","Decide al posto tuo"],1,"Mette in ordine una decisione complessa."]]},

{t:"Lavoro profondo",c:"app",tg:"Concentrarsi a lungo senza distrazioni produce risultati che il lavoro frammentato non dà.",d:2,
sp:"Cal Newport chiama lavoro profondo le attività svolte in piena concentrazione, senza interruzioni, che spingono le capacità al limite e creano valore: scrivere, progettare, studiare, risolvere problemi difficili. Il lavoro superficiale è fatto di email, messaggi e compiti semplici. Il modello ti invita a proteggere ogni giorno del tempo per il lavoro profondo.",
ap:["Ogni volta che passi da un'attività all'altra, parte dell'attenzione resta sulla precedente. Con continue interruzioni non si raggiunge mai la concentrazione piena. Per questo un'ora senza notifiche può valere più di una giornata intera spezzettata.","Strategie pratiche: blocchi di tempo fissi in agenda, telefono in un'altra stanza, un luogo dedicato, un rito di inizio. Il lavoro profondo è faticoso: si allena gradualmente, partendo da 30-60 minuti."],
ri:[["Giornate frammentate","Non hai mai più di 20 minuti senza interruzioni."],["Lavori importanti rimandati","Le email vengono sempre prima."],["Stanchezza senza risultati","Sei occupato tutto il giorno ma produci poco."]],
es:[["Lavoro","Un'analista blocca ogni mattina dalle 9 alle 11 per il progetto principale, con notifiche spente. Finisce in tre settimane ciò che rimandava da mesi."],["Studio","Uno studente studia 50 minuti con il telefono in cucina e fa una pausa. Impara di più in meno tempo."]],
ex:["Blocca in agenda un'ora di lavoro profondo per tre giorni questa settimana.","Durante quell'ora, metti il telefono in un'altra stanza.","Misura quante volte vieni interrotto in una giornata normale."],
q:["Qual è l'attività che merita la mia concentrazione piena?","Quando posso proteggere un blocco di tempo senza interruzioni?","Cosa mi distrae, e come lo allontano?"],
er:"Pretendere ore di concentrazione subito: va allenata gradualmente.",
qz:[["Cos'è il lavoro profondo?",["Lavorare di notte","Attività svolte in piena concentrazione senza distrazioni","Rispondere a tutte le email","Fare più cose insieme"],1,"Crea valore e spinge le capacità."],["Perché le interruzioni sono costose?",["Perché si perde tempo a rispondere","Perché parte dell'attenzione resta sull'attività precedente","Non sono costose","Perché fanno rumore"],1,"Il cambio di attività lascia un residuo di attenzione."]]},

{t:"Pratica deliberata",c:"app",tg:"Si migliora esercitandosi sui punti deboli, con obiettivi precisi e riscontri immediati.",d:2,
sp:"Lo psicologo Anders Ericsson ha studiato come gli esperti diventano tali. Non basta ripetere: chi suona la stessa canzone che sa già per anni non migliora. Serve la pratica deliberata: lavorare sui punti deboli, con obiettivi precisi, appena oltre le proprie capacità, ricevendo riscontri immediati e correggendo subito.",
ap:["La pratica deliberata è faticosa e poco divertente, perché si lavora proprio su ciò che non riesce. Un buon allenatore o insegnante aiuta a vedere gli errori e a progettare esercizi mirati. La famosa regola delle 10.000 ore è una semplificazione: conta la qualità delle ore, non solo il numero.","Per applicarla: scegli una competenza, scomponila in parti, individua la parte più debole, progetta un esercizio specifico, cerca un riscontro rapido (video, insegnante, misura), ripeti con correzioni."],
ri:[["Esperienza senza miglioramento","Fai una cosa da anni ma non migliori."],["Eviti ciò che non sai fare","Pratichi solo ciò che ti riesce."],["Nessun riscontro","Non sai se stai facendo bene."]],
es:[["Sport","Un giocatore di tennis allena per 20 minuti solo il rovescio, filmandosi. In un mese migliora più che in un anno di partite."],["Lavoro","Per parlare meglio in pubblico, registri una presentazione di 3 minuti, la riguardi, correggi un difetto alla volta."]],
ex:["Scegli una competenza e scrivi la sua parte più debole.","Progetta un esercizio di 15 minuti solo su quella parte e fallo tre volte questa settimana.","Trova un modo per avere un riscontro immediato: registrarti, misurare, chiedere."],
q:["Qual è la parte più debole di questa competenza?","Questo esercizio è appena oltre le mie capacità?","Come ricevo un riscontro immediato?"],
er:"Confondere la ripetizione di ciò che si sa fare con la pratica.",
qz:[["Cosa distingue la pratica deliberata dalla semplice ripetizione?",["Il numero di ore","Lavorare sui punti deboli con obiettivi precisi e riscontri","Divertirsi","Farlo in gruppo"],1,"Si lavora sui limiti con correzioni continue."],["Perché la pratica deliberata è faticosa?",["Perché è lunga","Perché si concentra su ciò che non riesce ancora","Perché è costosa","Non lo è"],1,"Lavorare sui punti deboli richiede sforzo."]]},

{t:"Design thinking",c:"lav",tg:"Capisci le persone, definisci il problema, genera idee, costruisci prototipi e prova.",d:2,
sp:"Il design thinking è un metodo per risolvere problemi partendo dalle persone. Ha cinque fasi: empatia (capire chi vive il problema), definizione (formulare il problema giusto), ideazione (generare molte idee), prototipo (costruire una versione semplice) e test (provarla con le persone). Le fasi si ripetono finché la soluzione funziona.",
ap:["Il metodo, reso popolare dallo studio IDEO e dalla d.school di Stanford, evita due errori: risolvere il problema sbagliato e innamorarsi della prima idea. Osservare le persone nella vita reale spesso rivela bisogni che non sanno nemmeno esprimere.","Puoi usarlo per problemi quotidiani: organizzare la cucina, migliorare il servizio di un negozio, preparare una lezione. Il punto chiave è provare presto con versioni semplici e imparare dalle reazioni."],
ri:[["Soluzioni che nessuno usa","Il risultato non risponde al bisogno reale."],["Problema mal definito","Non è chiaro cosa si vuole risolvere."],["Prima idea troppo amata","Si investe tutto su una sola soluzione."]],
es:[["Lavoro","Un ospedale vuole ridurre l'ansia dei bambini prima della risonanza. Osservandoli, trasforma la sala in un'avventura da pirati. L'ansia cala."],["Casa","Per rendere più facile la mattina in famiglia, osservi cosa succede, provi una postazione con zaini e chiavi vicino alla porta, e la migliori dopo una settimana."]],
ex:["Osserva per 15 minuti una persona che vive un problema che vuoi risolvere e annota cosa fa.","Scrivi il problema come domanda: «Come potremmo… per…?»","Costruisci in un'ora un prototipo semplice di una soluzione e fallo provare."],
q:["Chi vive questo problema, e cosa prova?","Sto risolvendo il problema giusto?","Qual è il prototipo più semplice che posso provare subito?"],
er:"Saltare la fase di osservazione e partire subito dalle idee.",
qz:[["Qual è la prima fase del design thinking?",["Prototipo","Empatia","Test","Vendita"],1,"Si parte dal capire le persone."],["Perché si costruiscono prototipi semplici?",["Per risparmiare","Per provare presto e imparare dalle reazioni","Per mostrarli in vetrina","Non servono"],1,"Si impara prima di investire troppo."]]},

{t:"La mentalità DevOps",c:"lav",tg:"Unire chi crea e chi gestisce, rilasciare spesso in piccoli passi e imparare dai dati.",d:3,
sp:"DevOps nasce nell'informatica per unire due gruppi che lavoravano separati: chi sviluppa il software e chi lo fa funzionare. L'idea è collaborare, automatizzare ciò che si ripete, rilasciare cambiamenti piccoli e frequenti, misurare cosa succede e correggere in fretta. Come mentalità vale anche fuori dall'informatica: abbattere i muri tra chi progetta e chi esegue.",
ap:["Quando chi progetta passa il lavoro «oltre il muro» a chi lo esegue, i problemi emergono tardi e nessuno se ne sente responsabile. Con cicli brevi e responsabilità condivisa, gli errori si vedono subito e sono piccoli. Un principio chiave: se una cosa è difficile, falla più spesso, così diventa facile.","Nella vita quotidiana puoi applicarlo così: piccoli cambiamenti frequenti invece di grandi rivoluzioni, automatizzare le routine, misurare i risultati, coinvolgere chi subisce le conseguenze delle tue decisioni."],
ri:[["Muri tra reparti","Chi decide non parla con chi esegue."],["Grandi rilasci rischiosi","Cambi tutto insieme e qualcosa si rompe."],["Lavoro manuale ripetuto","Si rifanno sempre gli stessi passaggi."]],
es:[["Lavoro","Il reparto vendite e il magazzino iniziano a fare un incontro di 15 minuti ogni mattina. Gli ordini impossibili da evadere diminuiscono."],["Casa","Invece di riorganizzare la casa una volta all'anno, sistemi un cassetto ogni settimana e controlli cosa funziona."]],
ex:["Individua due persone o reparti che lavorano separati e proponi un breve momento di confronto regolare.","Scegli un'attività ripetitiva e automatizzala o standardizzala.","Dividi un grande cambiamento in tre piccoli passi da provare uno alla volta."],
q:["Chi esegue o subisce questa decisione è coinvolto?","Posso fare questo cambiamento in passi più piccoli?","Cosa posso automatizzare?"],
er:"Pensare che riguardi solo gli strumenti: è soprattutto collaborazione.",
qz:[["Qual è un principio della mentalità DevOps?",["Rilasci grandi e rari","Cambiamenti piccoli e frequenti con collaborazione","Separare chi progetta da chi esegue","Evitare le misure"],1,"Piccoli passi rendono gli errori piccoli."],["«Se una cosa è difficile, falla più spesso». Perché?",["Per punizione","Perché la ripetizione la rende più facile e meno rischiosa","Per perdere tempo","Non ha senso"],1,"La frequenza riduce la difficoltà."]]},

{t:"DIBB: dai dati a una prova",c:"lav",tg:"Dati, intuizione, convinzione, scommessa: rendi esplicito il ragionamento dietro ogni decisione.",d:2,
sp:"DIBB è un modello usato in Spotify per prendere decisioni in modo trasparente. Si parte dai Dati (cosa osserviamo), si ricava un'Intuizione (cosa significano), si forma una Convinzione (cosa crediamo che succederà) e si fa una Scommessa (cosa proviamo per verificarlo). Scrivere i quattro passaggi rende chiaro il ragionamento e facile da discutere.",
ap:["Spesso le decisioni si basano su intuizioni non dette o su dati interpretati in modi diversi. DIBB rende visibile ogni passaggio, così gli altri possono mettere in discussione proprio il punto debole. E chiamare la decisione «scommessa» ricorda che può essere sbagliata e va verificata.","Puoi usarlo per decisioni personali: dati (dormo male quando uso il telefono la sera), intuizione (la luce mi tiene sveglio), convinzione (senza telefono dormirò meglio), scommessa (una settimana senza telefono dopo le 22)."],
ri:[["Decisioni senza motivazione","«Facciamo così» senza spiegare perché."],["Discussioni confuse","Si litiga senza capire su quale passaggio si è in disaccordo."],["Decisioni mai verificate","Si cambia qualcosa e non si controlla l'effetto."]],
es:[["Lavoro","Dati: metà dei clienti abbandona il carrello. Intuizione: le spese di spedizione arrivano a sorpresa. Convinzione: mostrarle prima ridurrà gli abbandoni. Scommessa: provarlo per un mese."],["Te stesso","Dati: spendo molto il fine settimana. Intuizione: esco senza un piano. Convinzione: con un budget spenderò meno. Scommessa: un mese con budget fisso."]],
ex:["Prendi una decisione recente e scrivila nei quattro passaggi DIBB.","In una discussione di gruppo, chiedi su quale dei quattro passaggi c'è disaccordo.","Trasforma una tua convinzione in una scommessa verificabile in due settimane."],
q:["Quali dati osservo?","Quale intuizione ne ricavo, e cosa credo succederà?","Quale scommessa posso fare per verificarlo?"],
er:"Saltare direttamente dai dati alla scommessa senza esplicitare intuizione e convinzione.",
qz:[["Cosa significa l'ultima B di DIBB?",["Budget","Scommessa (bet)","Beneficio","Blocco"],1,"La decisione è una prova da verificare."],["Qual è il vantaggio principale di DIBB?",["Velocizza ogni decisione","Rende visibile il ragionamento e permette di discutere il passaggio debole","Elimina i dati","Evita le prove"],1,"Ogni passaggio può essere messo in discussione."]]},

{t:"Una persona chiaramente responsabile",c:"evo",tg:"Ogni compito importante ha bisogno di un nome, non di un gruppo.",d:1,
sp:"In Apple si usa l'espressione DRI, persona direttamente responsabile: per ogni progetto o compito c'è un nome preciso che risponde del risultato. Quando la responsabilità è di «tutti», di fatto non è di nessuno. Il modello ti invita ad assegnare sempre un responsabile chiaro, anche quando a lavorare sono in tanti.",
ap:["Nei gruppi succede spesso che ognuno pensi che se ne occupi qualcun altro. È lo stesso meccanismo per cui più persone assistono a un incidente e meno probabilmente qualcuno interviene. Un nome chiaro elimina il dubbio.","Responsabile non significa fare tutto da solo: significa assicurarsi che le cose accadano, coordinare, chiedere aiuto e rispondere del risultato. Funziona in famiglia, tra amici, al lavoro."],
ri:[["«Pensavo lo facesse lui»","Un compito cade nel vuoto."],["Decisioni prese in riunione e mai eseguite","Nessuno se ne occupa dopo."],["Compiti condivisi","Molte persone, nessun nome."]],
es:[["Famiglia","Per il regalo di compleanno della nonna, invece di «ci pensiamo tutti», si decide che se ne occupa Luca. Il regalo arriva in tempo."],["Lavoro","Alla fine di ogni riunione, accanto a ogni decisione viene scritto un nome e una data."]],
ex:["Rivedi i compiti condivisi della tua settimana: ognuno ha un responsabile chiaro?","Alla prossima riunione o discussione di gruppo, chiedi: «Chi se ne occupa, ed entro quando?»","Offriti come responsabile di un compito che nessuno ha preso."],
q:["Chi è il responsabile di questo compito?","Lo sa, e ha i mezzi per farlo?","Entro quando?"],
er:"Confondere il responsabile con chi deve fare tutto il lavoro.",
qz:[["Cosa succede quando una responsabilità è «di tutti»?",["Viene fatta meglio","Spesso non se ne occupa nessuno","Si risparmia tempo","Nulla"],1,"Ognuno pensa che lo faccia un altro."],["Cosa fa la persona responsabile?",["Fa tutto da sola","Si assicura che il risultato arrivi, coordinando e chiedendo aiuto","Delega e dimentica","Controlla gli altri e basta"],1,"Risponde del risultato."]]},

{t:"DiSSS: progettare l'apprendimento",c:"app",tg:"Scomponi, seleziona, metti in sequenza e crea una posta in gioco per imparare più in fretta.",d:2,
sp:"Tim Ferriss propone un metodo per imparare velocemente una nuova abilità: Decostruire (scomponi l'abilità nelle sue parti), Selezionare (scegli il 20% che dà l'80% dei risultati), Sequenziare (decidi l'ordine giusto in cui impararle) e creare una posta in gioco, gli Stakes (una conseguenza concreta se non lo fai). Il metodo trasforma un obiettivo vago come «imparare lo spagnolo» in un piano preciso.",
ap:["Per una lingua, decostruire significa capire quali sono i mattoni (parole frequenti, verbi principali, pronuncia). Selezionare vuol dire concentrarsi sulle 1.000 parole più usate. Sequenziare significa partire dalle frasi utili nella vita quotidiana. La posta in gioco può essere un viaggio già prenotato o una scommessa con un amico.","Il metodo funziona bene per raggiungere un buon livello in poco tempo. Per l'eccellenza serve poi la pratica deliberata di lungo periodo."],
ri:[["Obiettivo di apprendimento vago","«Voglio imparare a cucinare»."],["Non sai da dove partire","L'abilità sembra enorme."],["Impegno che si spegne","Nessuna conseguenza se smetti."]],
es:[["Hobby","Vuoi imparare la chitarra. Scomponi, scegli i 4 accordi più usati nelle canzoni pop, impari prima il ritmo base e prometti a un amico di suonare una canzone alla sua festa."],["Lavoro","Per imparare Excel scegli le 10 funzioni più usate nel tuo lavoro e ti impegni a presentare un report al capo tra tre settimane."]],
ex:["Scegli un'abilità e scrivi le sue 5-10 parti principali.","Cerchia le 2-3 parti che danno più risultati e decidi l'ordine.","Crea una posta in gioco: una data, una promessa pubblica o un impegno con qualcuno."],
q:["Quali sono i mattoni di questa abilità?","Quale piccola parte dà la maggior parte dei risultati?","Cosa succede se non lo faccio?"],
er:"Restare per sempre sul 20% facile senza mai approfondire.",
qz:[["Cosa significa «selezionare» nel DiSSS?",["Scegliere un insegnante","Scegliere la piccola parte che dà più risultati","Scegliere il libro più lungo","Scegliere un orario"],1,"Si applica il principio di Pareto all'apprendimento."],["A cosa serve la posta in gioco?",["A spendere soldi","A creare una conseguenza che mantiene l'impegno","A rendere difficile imparare","A nulla"],1,"Una conseguenza concreta aumenta la costanza."]]},

{t:"Diversificazione",c:"qua",tg:"Non mettere tutte le uova nello stesso paniere.",d:1,
sp:"Diversificare significa distribuire risorse, rischi o speranze su più elementi diversi, così che un singolo problema non ti rovini. Vale per i risparmi, ma anche per i clienti di un lavoro autonomo, per le fonti di reddito, per le amicizie e per le fonti di soddisfazione nella vita.",
ap:["La diversificazione funziona quando gli elementi non vanno male tutti insieme. Avere dieci azioni dello stesso settore non è vera diversificazione. L'economista Harry Markowitz ha mostrato che combinare investimenti diversi riduce il rischio senza ridurre troppo il rendimento.","Ha un costo: rinunci a guadagni enormi se una scelta va molto bene. E troppa diversificazione disperde energie. Conviene quando non puoi permetterti di perdere tutto o quando non sai prevedere cosa andrà bene."],
ri:[["Un solo cliente, un solo reddito","Se lo perdi, perdi tutto."],["Identità legata a una cosa sola","Tutta la tua autostima dipende dal lavoro."],["Risparmi concentrati","Tutto in un solo investimento."]],
es:[["Soldi","Invece di comprare un'unica azione, investi in un fondo che contiene centinaia di aziende di settori e Paesi diversi."],["Te stesso","La tua felicità dipende tutta dal lavoro. Coltivi anche uno sport e un gruppo di amici: quando il lavoro va male, hai altri appoggi."]],
ex:["Elenca le tue fonti di reddito, di supporto e di soddisfazione. Dove dipendi da una sola?","Scegli un'area troppo concentrata e aggiungi una piccola alternativa.","Controlla se i tuoi investimenti sono davvero diversi o vanno tutti nella stessa direzione."],
q:["Cosa succede se questo singolo elemento va male?","Questi elementi possono andare male tutti insieme?","Sto diversificando troppo e disperdendo energie?"],
er:"Credere di essere diversificati quando gli elementi dipendono dagli stessi rischi.",
qz:[["Quando la diversificazione funziona meglio?",["Quando gli elementi vanno male tutti insieme","Quando gli elementi non dipendono dagli stessi rischi","Sempre allo stesso modo","Mai"],1,"Serve che gli elementi siano davvero diversi."],["Qual è un costo della diversificazione?",["Aumenta il rischio","Si rinuncia a guadagni enormi di una singola scelta","È illegale","Non ha costi"],1,"Riduce sia le perdite sia i picchi di guadagno."]]},

{t:"Dividere e affrontare",c:"rag",tg:"Scomponi un problema grande in parti piccole e risolvile una alla volta.",d:1,
sp:"Un problema enorme spaventa e paralizza. Diviso in parti più piccole diventa gestibile. Il modello, usato in informatica, in matematica e nella vita di tutti i giorni, consiste nello scomporre un problema in sotto-problemi, risolvere ciascuno separatamente e poi mettere insieme le soluzioni.",
ap:["Trasloco, tesi, ristrutturazione, riordino della casa: sembrano impossibili tutti insieme, ma sono composti da centinaia di passi semplici. Scomporre rende chiaro da dove partire, permette di dividere il lavoro tra più persone e dà la soddisfazione di vedere progressi.","Attenzione: alcune parti sono collegate e non si possono risolvere separatamente. E ricordati di rimettere insieme i pezzi: le soluzioni parziali devono funzionare anche nell'insieme."],
ri:[["Problema che spaventa","Non sai da dove cominciare."],["Procrastinazione","Rimandi perché il compito è troppo grande."],["Lavoro di gruppo disordinato","Tutti lavorano su tutto."]],
es:[["Casa","Il trasloco ti sembra impossibile. Lo dividi per stanze e per settimane: questa settimana solo libri e cantina."],["Studio","La tesi diventa: scegliere l'argomento, fare l'indice, scrivere un capitolo al mese, revisione finale."]],
ex:["Scegli il compito che rimandi da più tempo e scomponilo in almeno dieci passi.","Fai oggi il passo più piccolo della lista.","Per un progetto di gruppo, assegna ogni parte a una persona."],
q:["In quali parti posso dividere questo problema?","Quale parte posso risolvere oggi?","Le soluzioni parziali funzionano anche insieme?"],
er:"Dividere senza poi controllare che le parti stiano insieme.",
qz:[["Cosa suggerisce il modello davanti a un problema enorme?",["Affrontarlo tutto in una volta","Scomporlo in parti più piccole","Rimandarlo","Delegarlo interamente"],1,"Le parti piccole sono gestibili."],["Qual è un rischio del modello?",["Nessuno","Le parti possono essere collegate e le soluzioni non combaciare","Va troppo veloce","È troppo semplice"],1,"Bisogna verificare che l'insieme funzioni."]]},

{t:"Apprendimento a doppio ciclo",c:"app",tg:"Non correggere solo l'azione: metti in discussione le convinzioni che l'hanno guidata.",d:3,
sp:"Chris Argyris distingue due modi di imparare dagli errori. Nel ciclo singolo correggi l'azione: il termostato accende il riscaldamento quando fa freddo. Nel doppio ciclo ti chiedi se l'obiettivo e le convinzioni di partenza sono giusti: forse la temperatura impostata è sbagliata. Molti problemi ricorrenti si risolvono solo con il doppio ciclo.",
ap:["Se un piano fallisce e cambi solo le tattiche, potresti continuare a sbagliare perché l'idea di fondo è errata. Ad esempio, un'azienda che perde clienti abbassa i prezzi (ciclo singolo), invece di chiedersi se il suo prodotto risponde ancora ai bisogni (doppio ciclo).","Il doppio ciclo è difficile perché mette in discussione ciò in cui crediamo e a volte la nostra identità. Domande utili: perché pensavamo che questo avrebbe funzionato? Quale convinzione era sbagliata? Cosa diamo per scontato?"],
ri:[["Stessi problemi dopo ogni correzione","Cambi le azioni, non i risultati."],["Obiettivi mai messi in discussione","Si cerca solo come raggiungerli meglio."],["Difesa delle proprie idee","Ogni critica viene respinta."]],
es:[["Te stesso","Cambi dieta per la terza volta senza risultati. Con il doppio ciclo ti chiedi se il problema è la dieta o il mangiare per stress."],["Lavoro","Una scuola aggiunge compiti perché i voti calano. Poi si chiede se il metodo di insegnamento sia adatto agli studenti di oggi."]],
ex:["Pensa a un problema ricorrente e scrivi la convinzione che sta alla base delle tue soluzioni.","Chiedi a qualcuno di fuori cosa pensa che tu stia dando per scontato.","Dopo il prossimo errore, rispondi a due domande: cosa cambio nell'azione? Cosa cambio nel modo di pensare?"],
q:["Sto correggendo solo l'azione o anche il modo di pensare?","Quale convinzione ha guidato questa scelta?","Cosa sto dando per scontato?"],
er:"Mettere in discussione tutto, sempre: alcune convinzioni sono solide e utili.",
qz:[["Cosa caratterizza l'apprendimento a doppio ciclo?",["Ripetere l'azione","Mettere in discussione obiettivi e convinzioni di partenza","Imparare due volte","Seguire le regole"],1,"Si interroga ciò che ha guidato l'azione."],["Un'azienda perde clienti e abbassa solo i prezzi. Che tipo di apprendimento è?",["Doppio ciclo","Ciclo singolo","Nessuno","Triplo ciclo"],1,"Cambia la tattica senza mettere in discussione le premesse."]]},

{t:"EAST: facilitare un comportamento",c:"app",tg:"Per far fare qualcosa, rendilo facile, attraente, sociale e tempestivo.",d:1,
sp:"Il Behavioural Insights Team britannico ha riassunto in quattro parole come incoraggiare un comportamento: renderlo Facile (Easy), Attraente, Sociale e Tempestivo (Timely). Se vuoi che tu o altri facciano qualcosa, invece di insistere con le spiegazioni, lavora su questi quattro aspetti.",
ap:["Facile: togli passaggi, imposta la scelta giusta come predefinita. Attraente: rendi il comportamento visibile, personale, gratificante. Sociale: mostra che altri lo fanno, crea impegni con altre persone. Tempestivo: intervieni nel momento in cui le persone sono più disposte a cambiare, come all'inizio di un anno o dopo un trasloco.","Con questi principi il governo britannico ha aumentato il pagamento delle tasse aggiungendo una frase come «la maggior parte delle persone della tua zona paga in tempo». Puoi usarli per abitudini personali, figli, colleghi."],
ri:[["Spiegazioni che non funzionano","Le persone sanno, ma non fanno."],["Procedure complicate","Troppi passaggi scoraggiano."],["Momenti di cambiamento","Nuovo lavoro, nuova casa, inizio d'anno."]],
es:[["Salute","Vuoi bere più acqua: bottiglia sempre sulla scrivania (facile), con una borraccia che ti piace (attraente), sfida con un collega (sociale), promemoria dopo pranzo (tempestivo)."],["Famiglia","Per far riordinare i giochi: cesta vicino al tappeto, musica allegra, tutti insieme, subito dopo cena."]],
ex:["Scegli un comportamento che vuoi incoraggiare e scrivi un'idea per ciascuna delle quattro lettere.","Togli almeno un passaggio che rende difficile una buona abitudine.","Approfitta di un momento di cambiamento imminente per iniziare qualcosa."],
q:["Come posso renderlo più facile?","Cosa lo rende attraente e sociale?","Qual è il momento migliore per proporlo?"],
er:"Puntare solo sull'attrattiva o sull'informazione e ignorare la facilità.",
qz:[["Cosa significa la T di EAST?",["Tecnico","Tempestivo","Tradizionale","Tranquillo"],1,"Il momento giusto aumenta l'effetto."],["Qual è spesso la leva più potente?",["Spiegare meglio","Rendere il comportamento facile","Punire","Ripetere"],1,"Ridurre gli ostacoli ha effetti grandi."]]},

{t:"La matrice di Eisenhower",c:"app",tg:"Distingui ciò che è urgente da ciò che è importante.",d:1,
sp:"La matrice prende il nome dal presidente americano Dwight Eisenhower, a cui si attribuisce la frase «ciò che è importante raramente è urgente, e ciò che è urgente raramente è importante». Dividi le attività in quattro riquadri: importanti e urgenti (fai subito), importanti ma non urgenti (pianifica), urgenti ma non importanti (delega), né urgenti né importanti (elimina).",
ap:["Le attività urgenti gridano: telefonate, messaggi, scadenze altrui. Quelle importanti, come salute, relazioni, crescita, progetti di lungo periodo, aspettano in silenzio. Se ti occupi solo dell'urgente, l'importante non arriva mai, finché diventa un'emergenza.","Il riquadro più prezioso è il secondo: importante ma non urgente. Dedicagli tempo fisso ogni settimana. Così riduci anche le emergenze del primo riquadro, perché molte nascono da cose importanti trascurate."],
ri:[["Sempre in emergenza","Corri da un'urgenza all'altra."],["Progetti importanti rimandati","Non c'è mai tempo per ciò che conta."],["Interruzioni continue","Altri decidono la tua agenda."]],
es:[["Salute","Il controllo medico è importante ma non urgente: lo prenoti adesso, prima che diventi urgente."],["Lavoro","Un collega ti chiede di rivedere una presentazione non tua all'ultimo minuto. È urgente per lui, non importante per te: proponi un'altra persona."]],
ex:["Elenca le attività della settimana e mettile nei quattro riquadri.","Blocca due ore in agenda per un'attività importante ma non urgente.","Elimina o delega almeno due attività degli ultimi due riquadri."],
q:["Questa cosa è importante o solo urgente?","Cosa di importante sto rimandando?","Cosa posso delegare o eliminare?"],
er:"Mettere tutto nel riquadro «importante e urgente».",
qz:[["Cosa fare con le attività importanti ma non urgenti?",["Eliminarle","Pianificarle con tempo dedicato","Farle subito","Delegarle"],1,"Sono il riquadro più prezioso."],["Una chiamata urgente ma poco importante va...",["Fatta subito sempre","Delegata o ridotta","Ignorata per sempre","Pianificata tra un mese"],1,"L'urgenza non coincide con l'importanza."]]},

{t:"L'effetto ELIZA",c:"com",tg:"Tendiamo ad attribuire comprensione umana alle macchine che sembrano parlare come noi.",d:2,
sp:"Negli anni Sessanta Joseph Weizenbaum creò ELIZA, un semplice programma che imitava uno psicoterapeuta ripetendo le frasi dell'utente sotto forma di domanda. Molte persone, compresa la sua segretaria, si convinsero che il programma le capisse davvero. L'effetto ELIZA è la tendenza ad attribuire comprensione, emozioni e intenzioni alle macchine che usano un linguaggio umano.",
ap:["Oggi l'effetto è più forte che mai, con assistenti vocali e chatbot molto più capaci di ELIZA. Il loro modo di parlare ci spinge a fidarci, a confidarci e a credere che sappiano più di quanto sanno. Questo può portare a seguire consigli senza verificarli o a creare legami emotivi.","Usare questi strumenti è utile, ma conviene ricordare cosa sono: sistemi che producono testo plausibile, che possono sbagliare con grande sicurezza. Verifica le informazioni importanti, soprattutto su salute, soldi e diritti, e non sostituire le relazioni umane."],
ri:[["Fiducia automatica","Credi a una risposta perché è scritta bene."],["Confidenze a una macchina","Ti senti capito da un programma."],["Attribuire intenzioni","«Il computer ce l'ha con me»."]],
es:[["Salute","Un chatbot ti dà un consiglio su un farmaco con tono sicuro. Lo verifichi con il farmacista prima di seguirlo."],["Te stesso","Ti accorgi di parlare ogni sera con un assistente virtuale invece che con gli amici. Usi la chat per organizzare un incontro con loro."]],
ex:["La prossima volta che un'app o un chatbot ti dà un'informazione importante, verificala con una fonte indipendente.","Nota quando ti viene spontaneo ringraziare o arrabbiarti con una macchina: cosa ti fa sentire così?","Scrivi tre cose per cui usi un assistente digitale e tre per cui preferisci una persona."],
q:["Sto attribuendo a questo strumento una comprensione che non ha?","Ho verificato questa informazione?","Sto sostituendo una relazione umana con una macchina?"],
er:"Passare all'estremo opposto e rifiutare strumenti utili per paura.",
qz:[["Cos'è l'effetto ELIZA?",["Un virus informatico","La tendenza ad attribuire comprensione umana alle macchine che parlano come noi","Un metodo di programmazione","Una terapia"],1,"Il linguaggio umano ci fa supporre una mente."],["Cosa conviene fare con i consigli importanti di un chatbot?",["Seguirli subito","Verificarli con una fonte indipendente o un esperto","Ignorarli tutti","Condividerli"],1,"Possono essere sbagliati anche se scritti con sicurezza."]]}
);
